import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BEmfQga0.js";const g=JSON.parse('{"title":"Adapter Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"host-adapter-development/adapter-architecture.md","filePath":"host-adapter-development/adapter-architecture.md","lastUpdated":1788258471000}'),o={name:"host-adapter-development/adapter-architecture.md"};function n(d,t,i,s,c,p){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="adapter-architecture" tabindex="-1">Adapter Architecture <a class="header-anchor" href="#adapter-architecture" aria-label="Permalink to &quot;Adapter Architecture&quot;">​</a></h1><p>Host adapters are the integration layer between a specific coding-agent host and TokenPilot.</p><h2 id="current-adapters" tabindex="-1">Current Adapters <a class="header-anchor" href="#current-adapters" aria-label="Permalink to &quot;Current Adapters&quot;">​</a></h2><p>From <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Host</th><th style="text-align:left;">Status</th><th style="text-align:left;">Integration Mode</th><th style="text-align:left;">Install Surface</th></tr></thead><tbody><tr><td style="text-align:left;">OpenClaw</td><td style="text-align:left;">production</td><td style="text-align:left;">bundled plugin + embedded runtime</td><td style="text-align:left;"><code>pnpm component:install:tokenpilot:openclaw</code> or <code>npm --prefix components/adapters/openclaw run install:release</code></td></tr><tr><td style="text-align:left;">Codex CLI</td><td style="text-align:left;">available</td><td style="text-align:left;">hooks + local Responses proxy + shared CLI</td><td style="text-align:left;"><code>npm --prefix components/adapters/codex run build</code> then <code>npm --prefix components/adapters/codex run install:codex</code></td></tr><tr><td style="text-align:left;">Claude Code</td><td style="text-align:left;">available</td><td style="text-align:left;">gateway routing + observability hooks + shared CLI</td><td style="text-align:left;"><code>npm --prefix components/adapters/claude-code run build</code> then <code>npm --prefix components/adapters/claude-code run install:claude-code</code></td></tr><tr><td style="text-align:left;">DeepSeek Harness</td><td style="text-align:left;">available</td><td style="text-align:left;">Cordis plugin + durable projection + compatibility smoke</td><td style="text-align:left;"><code>pnpm --filter @lightrsi/deepseek-harness-adapter compatibility:smoke -- --dsh-checkout=/absolute/path/to/deepseek-harness</code></td></tr></tbody></table><h2 id="adapter-responsibilities" tabindex="-1">Adapter Responsibilities <a class="header-anchor" href="#adapter-responsibilities" aria-label="Permalink to &quot;Adapter Responsibilities&quot;">​</a></h2><p>From <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/README.md" target="_blank" rel="noreferrer">adapters/README.md</a>:</p><p>Keep these inside the adapter:</p><ul><li>Host install and uninstall flow</li><li>Host config mutation</li><li>Request / response hook wiring</li><li>Session and transcript bridging</li><li>Host-specific command registration</li><li>Runtime bootstrap and doctor checks</li><li>Host-owned path resolution</li></ul><h2 id="shared-packages" tabindex="-1">Shared Packages <a class="header-anchor" href="#shared-packages" aria-label="Permalink to &quot;Shared Packages&quot;">​</a></h2><p>Host-agnostic logic lives in shared packages under <code>components/packages/</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Package</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><code>components/packages/foundation/host-adapter/</code></td><td style="text-align:left;">Host abstraction contracts and envelope bridge helpers</td></tr><tr><td style="text-align:left;"><code>components/packages/foundation/kernel/</code></td><td style="text-align:left;">Shared contracts, events, and runtime-facing types</td></tr><tr><td style="text-align:left;"><code>components/packages/foundation/runtime-core/</code></td><td style="text-align:left;">Host-agnostic reduction, recovery, and archive primitives</td></tr><tr><td style="text-align:left;"><code>components/packages/{foundation,features}/**</code></td><td style="text-align:left;">Policy, history, and memory logic</td></tr><tr><td style="text-align:left;"><code>components/packages/foundation/product-surface/</code></td><td style="text-align:left;">Shared command semantics for the standalone CLI</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./adapter-testing">Adapter Testing</a></li><li><a href="./adding-new-host">Adding a New Host</a></li><li><a href="./configuration-integration">Configuration Integration</a></li><li><a href="./hook-proxy-integration">Hook and Proxy Integration</a></li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/docs/adapter-playbook.md" target="_blank" rel="noreferrer">Adapter Playbook</a></li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a></li></ul>',14)])])}const u=e(o,[["render",n]]);export{g as __pageData,u as default};
